class Solution {
public:
    bool isConsecutive(vector<int>& nums) {
        unordered_set<int> values(nums.begin(), nums.end());
        auto limits = minmax_element(nums.begin(), nums.end());
        return values.size() == nums.size()
            && (long long)*limits.second - *limits.first + 1 == nums.size();
    }
};
